  url
    .toLowerCase()
    .replace(/https?:\/\//, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");

export const screenshotTask = task({
  id: `puppeteer-screenshot-${trialId}`,
  run: async (payload: { url: string }) => {
    const slug = slugifyUrl(payload.url) || "screenshot";
